-- Passage rg6-theme-summary-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('179ba9a1-e7d8-5901-ae6b-a2ff5d8f8340', 'rg6-theme-summary-p02', (select id from public.skills where slug = 'read-g6-theme-summary'), null,
        '6-8', $q$The Wheel Remembers Nothing$q$, $q$The first bowl slumped like a tired hat.
The second cracked along its side.
The third one wobbled, leaned and fell,
and still I pressed my palms and tried.

My teacher, Ms. Okonkwo, smiled
and scraped the clay back in the pail.
"The wheel remembers nothing, so
it never counts the times you fail."

At home I practiced in my head:
the press, the lift, the steady hand.
I watched my brother learn to skate
and fall a hundred times to stand.

I learned to wet my hands just so,
to brace my elbows on my knees,
to let the spinning do the work
and raise the wall with gentle ease.

By spring my shelf held seven cups,
lopsided, simple, but complete.
I drink my cocoa from the worst
and think of every slow defeat.

It leans a little to the left.
Its handle is a bit too wide.
It holds the story of my hands,
and every time I sat and tried.$q$, 'draft')
