  ('2d290144-550a-530e-9869-ea448ec65cb9', null, (select id from public.skills where slug = 'read-g6-theme-summary'), null, 'medium',
   $q$How do the opening paragraphs help develop the theme?$q$, $q$[{"text":"They show how badly Rafael wants the record, which makes his honest choice harder.","is_correct":true},{"text":"They explain the rules of the long jump so readers can judge the official.","is_correct":false,"misconception_token":"misreads-purpose"},{"text":"They show that Rafael has never jumped farther than three meters before.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"They suggest that Rafael does not care very much about long jumping.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$They show how badly Rafael wants the record, which makes his honest choice harder.$q$, $q$Rafael "wanted that record more than anything," so giving it up shows how much honesty means to him. The text says his best mark was four meters, so the choice saying he "has never jumped farther than three meters" gets the facts wrong.$q$, 'draft', '5b05a701-5743-55e6-85f7-85d5889a54ef')
