  ('896d601c-0979-5d90-82b5-dc69a678ec33', null, (select id from public.skills where slug = 'read-g6-theme-summary'), null, 'easy',
   $q$Which statement best expresses the theme of the poem?$q$, $q$[{"text":"Stargazing is dangerous on cold winter nights in the hills.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"People should stay quiet whenever a guide is speaking to a group.","is_correct":false,"misconception_token":"too-narrow"},{"text":"Feeling small in a huge universe can fill a person with wonder instead of fear.","is_correct":true},{"text":"Telescopes are the most important invention in all of science.","is_correct":false,"misconception_token":"overgeneralizes"}]$q$::jsonb, $q$Feeling small in a huge universe can fill a person with wonder instead of fear.$q$, $q$The speaker feels "as small as one grain of sand, / and yet I felt no fear," and walks home full of thoughts. The guide asks for quiet only so eyes can adjust, which is a detail, not the poem's message.$q$, 'draft', 'f0c7f22a-0c88-5440-a63c-8da729bb5b11')
