-- Passage rg6-theme-summary-p07
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('bd979aea-5281-595d-9d5a-52b19c1e442b', 'rg6-theme-summary-p07', (select id from public.skills where slug = 'read-g6-theme-summary'), null,
        '6-8', $q$Second Violin$q$, $q$When the orchestra list went up on the music room door, Lucia found her name in the second violin section. Her best friend, Hana, had been chosen for first violin, which played the melody. Lucia read the list twice, hoping she had made a mistake.

At the first rehearsal, the second violins played long, low notes while the first violins soared above them. Lucia's part looked boring on the page: whole notes, repeated rhythms and almost no high notes at all. She played it without really listening.

"Second violins," said Mr. Adeyemi, the director, tapping his stand. "Let's hear the first violins alone for a moment."

Hana's section played the melody by itself. It sounded thin and floaty, like a voice singing in an empty gym. Then Mr. Adeyemi had everyone play together. Suddenly the melody had something to rest on. It sounded warm and full.

"The melody gets the attention," Mr. Adeyemi said. "But the harmony is what makes it sound like music. If you play your part halfway, the whole piece sinks."

After that, Lucia practiced her long notes every night. She learned exactly when her part should swell and when it should fade. She started listening to the cellos, the flutes and the first violins, fitting her sound into theirs.

At the spring concert, the audience clapped loudly after the final piece. Nobody in the crowd knew which notes had been hers. Lucia did not mind. She had heard the music around her own part, and she knew it would have been weaker without it.$q$, 'draft')
