-- Passage rg6-theme-summary-p08
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('270a4759-817f-556e-8b32-3e16408a46b5', 'rg6-theme-summary-p08', (select id from public.skills where slug = 'read-g6-theme-summary'), null,
        '6-8', $q$Reading the Clouds$q$, $q$Every Sunday, Kofi visited his grandfather, who lived alone in a small house at the edge of town. This spring, Kofi's mother had given him a job: teach Grandpa Kwame to use the new tablet so the family could video call him during the week.

It did not go smoothly. Grandpa Kwame pressed the screen too hard, then too softly. He kept closing the call by accident. "These buttons hide from me," he grumbled.

Kofi tried not to sigh. He showed his grandfather the green button again, and then again.

After an hour, they both needed a break. They sat on the porch with glasses of lemonade. Grandpa Kwame looked up and pointed. "See those clouds, high and thin like feathers? Rain will come by tomorrow night."

Kofi laughed. "How could you know that?"

"I farmed for forty years before I moved here," his grandfather said. "The sky was my weather report." He showed Kofi how puffy clouds that grow tall in the afternoon can mean a storm, and how a ring around the moon can warn of rain.

Kofi was surprised to find himself asking question after question. His grandfather was a patient teacher, explaining things more than once without complaint. Kofi thought about how he had sighed inside the house.

The next night, rain drummed on Kofi's window. A moment later, the tablet chimed. Grandpa Kwame's face filled the screen, a little too close to the camera.

"Did I do it right?" he asked.

"You did it right," Kofi said. "And so did your clouds."$q$, 'draft')
