values
  ('64c4137a-6e15-5bc9-87d6-a3f565b06ee1', null, (select id from public.skills where slug = 'read-g7-authors-purpose'), null, 'hard',
   $q$Which sentence best states the belief that separates the author's view from the historians' view?$q$, $q$[{"text":"\"The museum is planning new signs next year.\"","is_correct":false,"misconception_token":"irrelevant-detail"},{"text":"\"They point out that the job officially belonged to the captain, and that the government paid him.\"","is_correct":false,"misconception_token":"confuses-opposing-view"},{"text":"\"History should record the people who did the work, not only the people whose names were on the paperwork.\"","is_correct":true},{"text":"\"Every evening, someone had to climb ninety steps, trim the wick, and fill the lamp with oil.\"","is_correct":false,"misconception_token":"detail-not-belief"}]$q$::jsonb, $q$"History should record the people who did the work, not only the people whose names were on the paperwork."$q$, $q$This sentence states the principle behind the author's whole argument, which the historians do not share because they focus on the official job. The sentence about the official job states the historians' reason, not the author's belief.$q$, 'draft', 'eafa22fb-ff01-57f2-a13a-058b0e050868')
