-- Passage rg7-connections-p04
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('86b7274b-072c-5fea-95d6-ab4852445ebb', 'rg7-connections-p04', (select id from public.skills where slug = 'read-g7-connections'), null,
        '6-8', $q$A Wall That Brought a Street Together$q$, $q$The brick wall behind the Oakdale laundromat was once covered with faded paint and scribbles. Artist Kwame Lindqvist walked past it every day on his way to his studio. He thought the blank wall could tell the story of the neighborhood, but he knew he could not tell that story alone.

Instead of sketching a design himself, Lindqvist set up a table outside the laundromat for three Saturdays. He asked neighbors to share memories of the street. An older woman described the bakery that used to stand on the corner. A group of teenagers talked about the pickup basketball games at the nearby court. A family who had recently moved from overseas brought photos of the flowers from their home country.

Lindqvist combined these memories into one large sketch. He showed it at a community meeting, and people suggested changes. The teenagers asked for the basketball court to be larger, and the baker's grandson brought a photo of the old sign so it could be painted accurately.

Painting took six weeks. Lindqvist outlined the shapes, but volunteers of all ages filled in the colors. Neighbors who had lived on the same block for years without speaking found themselves sharing paint trays.

When the mural was finished, something else changed. The laundromat owner added benches facing the wall. People began stopping to point out their own memories to friends. Since then, the street has held a small festival in front of the mural every summer. The wall that once made the block look neglected has become the place where neighbors gather.$q$, 'draft')
